const html="<!DOCTYPE html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#184c42\"><meta name=\"description\" content=\"Savoir avant de réserver si un cabinet médical vous est accessible. accescompanion montre ce qui est connu, ce qui ne l’est pas, et reste pendant la visite.\"><title>accescompanion</title>\n<style>\n:root{--ink:#17332c;--green:#1b5344;--mint:#eaf1e9;--cream:#f6f8f4;--line:#e3ebe4;--muted:#5d6e66;--amber:#88601c;--amber-bg:#fbf3e3;--red:#9a4234;--red-bg:#f9ece9;--grey-bg:#eef0ee}\n*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-size:17px;line-height:1.5}\na{color:var(--green)}button,a{outline-offset:4px}:focus-visible{outline:3px solid #b16830}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}.skip{position:absolute;top:-100px}.skip:focus{top:8px;left:12px;z-index:5;background:#fff;padding:12px}\nheader{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 28px;border-bottom:1px solid var(--line)}\n.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink)}.mark{width:36px;height:36px;display:block;flex:none}\n.wordmark{font-weight:720;letter-spacing:-.06em;font-size:21px;line-height:1}.wordmark i{font-family:Georgia,\"Iowan Old Style\",serif;font-style:italic;font-weight:520;color:var(--green);letter-spacing:-.03em}\nnav{display:flex;gap:18px}nav a{color:var(--muted);text-decoration:none;font-size:15px}nav a:hover{color:var(--green)}\n.wrap{max-width:1080px;margin:0 auto;padding:0 24px}\nsection{padding:72px 0}section+section{border-top:1px solid var(--line)}\n.kicker{font-size:13px;letter-spacing:.08em;font-weight:700;color:var(--green);margin:0 0 16px;text-transform:uppercase}\nh1{font-size:clamp(36px,5.4vw,60px);font-weight:700;letter-spacing:-.045em;line-height:1.04;margin:0}\nh1 em{font-family:Georgia,\"Iowan Old Style\",serif;font-weight:400;font-style:italic;color:var(--green);letter-spacing:-.02em}\nh2{font-size:clamp(26px,3.2vw,34px);font-weight:680;letter-spacing:-.03em;line-height:1.15;margin:0 0 12px}\nh3{font-size:18px;margin:0 0 6px;letter-spacing:-.01em}\n.lede{font-size:20px;color:#3e564b;max-width:34rem;margin:22px 0 0}\n.hero{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:56px;align-items:center;padding:80px 0 72px}\n.cta{display:flex;flex-wrap:wrap;gap:12px;margin:32px 0 0}\n.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:12px 20px;border-radius:12px;font-weight:650;font-size:16px;text-decoration:none}\n.btn.primary{background:var(--green);color:#fff}.btn.primary:hover{background:#143f34}\n.btn.ghost{border:1.5px solid #c9d8cc;color:var(--green);background:#fff}.btn.ghost:hover{border-color:var(--green)}\n.chips{margin:28px 0 0}.chips p{font-size:14px;color:var(--muted);margin:0 0 10px}\n.chips ul{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:0;padding:0}\n.chips a{display:inline-block;padding:8px 14px;border-radius:999px;background:var(--mint);color:var(--green);text-decoration:none;font-size:15px;font-weight:550}.chips a:hover{background:#dce9da}\n.facts{display:flex;flex-wrap:wrap;gap:6px 18px;margin:28px 0 0;padding:0;list-style:none;font-size:14px;color:var(--muted)}.facts li::before{content:\"·\";margin-right:8px;color:#a9b8ae}.facts li:first-child::before{content:none}\n.sample{background:var(--cream);border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 18px 48px #193b3412}\n.sample-head{display:flex;justify-content:space-between;align-items:start;gap:12px;margin-bottom:16px}\n.sample-head b{display:block;font-size:17px}.sample-head span{font-size:14px;color:var(--muted)}\n.tag{font-size:11px;letter-spacing:.06em;font-weight:700;text-transform:uppercase;color:var(--muted);border:1px solid #cfd8d1;border-radius:6px;padding:3px 7px;white-space:nowrap}\n.rows{list-style:none;margin:0;padding:0;display:grid;gap:8px}\n.rows li{display:flex;justify-content:space-between;align-items:center;gap:12px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:11px 14px;font-size:15px}\n.st{font-size:13px;font-weight:650;border-radius:999px;padding:3px 10px;white-space:nowrap}\n.st.ok{background:var(--mint);color:var(--green)}.st.decl{background:var(--amber-bg);color:var(--amber)}.st.unk{background:var(--grey-bg);color:#55605a}.st.bad{background:var(--red-bg);color:var(--red)}\n.ask{margin:14px 0 0;font-size:14px;color:#3e564b;background:#fff;border-left:3px solid var(--amber);padding:10px 14px;border-radius:0 10px 10px 0}\n.stat{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px;align-items:center}\n.big{font-size:clamp(72px,11vw,120px);font-weight:760;letter-spacing:-.06em;line-height:.9;margin:0 0 14px}\n.stat-text{font-size:clamp(22px,2.6vw,28px);font-weight:620;letter-spacing:-.025em;line-height:1.2;margin:0}\n.bars{display:grid;gap:18px}.bar-label{display:flex;justify-content:space-between;font-size:15px;margin-bottom:6px}.bar-label b{font-variant-numeric:tabular-nums}\n.track{height:14px;background:var(--grey-bg);border-radius:999px;overflow:hidden}.fill{height:100%;border-radius:999px}\n.why{font-size:18px;color:#3e564b;margin:28px 0 0;max-width:32rem}\n.source{font-size:13px;color:var(--muted);margin:14px 0 0}\n.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;list-style:none;padding:0;margin:32px 0 0;counter-reset:s}\n.steps li{border:1px solid var(--line);border-radius:16px;padding:22px;background:#fff;counter-increment:s;display:flex;flex-direction:column}\n.steps li::before{content:counter(s);display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:var(--mint);color:var(--green);font-weight:750;margin-bottom:14px}\n.steps p{margin:0;color:#3e564b;font-size:16px;flex:1}.steps a{margin-top:16px;font-weight:650;font-size:15px}\n.section-lede{font-size:18px;color:#3e564b;max-width:40rem;margin:0}\n.legend{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;list-style:none;padding:0;margin:32px 0 0}\n.legend li{border:1px solid var(--line);border-radius:14px;padding:16px 18px;background:#fff}.legend .st{display:inline-block;margin-bottom:8px}.legend p{margin:0;font-size:15px;color:#3e564b}\n.legend li.later{background:var(--cream);border-style:dashed}.legend .soon{font-size:12px;color:var(--muted);margin-left:6px}\n.note{margin:24px 0 0;font-size:15px;color:#3e564b;max-width:44rem}\n.limits{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px 32px;list-style:none;padding:0;margin:24px 0 0}\n.limits li{font-size:15px;color:#3e564b;padding-left:18px;position:relative}.limits li::before{content:\"\";position:absolute;left:0;top:.6em;width:7px;height:7px;border-radius:50%;background:#b8c6bb}\nfooter{border-top:1px solid var(--line);background:var(--cream);font-size:13px;color:var(--muted)}footer .wrap{padding:28px 24px}footer p{margin:4px 0}\n@media(max-width:860px){.hero,.stat{grid-template-columns:1fr;gap:40px}.steps{grid-template-columns:1fr}.hero{padding:48px 0}}\n@media(max-width:640px){header{padding:14px 16px;flex-wrap:wrap}nav{gap:14px}.wrap{padding:0 16px}section{padding:52px 0}.btn{flex:1 1 100%}.lede{font-size:18px}}\n@media(prefers-reduced-motion:no-preference){.btn,.chips a{transition:background .15s,border-color .15s}}\n</style></head>\n<body><a class=\"skip\" href=\"#main\">Aller au contenu</a>\n<header><a class=\"brand\" href=\"/\" aria-label=\"accescompanion, accueil\"><svg class=\"mark\" viewBox=\"0 0 40 40\" aria-hidden=\"true\"><rect width=\"40\" height=\"40\" rx=\"12\" fill=\"#1b5344\"/><path d=\"M12 29V17.2a8 8 0 0 1 16 0V29\" fill=\"none\" stroke=\"#f3f6f1\" stroke-width=\"2.3\" stroke-linecap=\"round\"/><circle cx=\"20\" cy=\"19.2\" r=\"2.15\" fill=\"#d7ebc8\"/></svg><b class=\"wordmark\">acces<i>companion</i></b></a><nav aria-label=\"Navigation principale\"><a href=\"/cabinets\">Les cabinets</a><a href=\"/consultation\">L’échange</a></nav></header>\n<main id=\"main\">\n\n<div class=\"wrap\"><div class=\"hero\">\n <div>\n  <p class=\"kicker\">Paris · médecine</p>\n  <h1>Savoir <em>avant</em> de réserver si le cabinet vous est accessible.</h1>\n  <p class=\"lede\">Décrivez votre besoin avec vos mots. accescompanion compare les cabinets sur ce qui est documenté, montre d’où vient chaque information, et dit clairement ce qui reste inconnu.</p>\n  <div class=\"cta\"><a class=\"btn primary\" href=\"/cabinets\">Trouver un cabinet</a><a class=\"btn ghost\" href=\"/consultation\">Suivre un rendez-vous</a></div>\n  <div class=\"chips\"><p id=\"chips-label\">Ou commencez par un besoin :</p><ul aria-labelledby=\"chips-label\">\n   <li><a href=\"/cabinets#besoin=fauteuil\">Fauteuil roulant</a></li>\n   <li><a href=\"/cabinets#besoin=audition\">Besoin auditif</a></li>\n   <li><a href=\"/cabinets#besoin=vision\">Besoin visuel</a></li>\n   <li><a href=\"/cabinets#besoin=sans-marche\">Entrée sans marche</a></li>\n  </ul></div>\n  <ul class=\"facts\"><li>510 cabinets parisiens</li><li>Données Accès Libre</li><li>Rien n’est enregistré</li></ul>\n </div>\n\n <figure class=\"sample\" aria-labelledby=\"sample-cap\" style=\"margin:0\">\n  <div class=\"sample-head\"><div><b id=\"sample-cap\">Cabinet de médecine générale</b><span>Paris 11<sup>e</sup></span></div><span class=\"tag\">Exemple</span></div>\n  <ul class=\"rows\">\n   <li>Entrée sans marche <span class=\"st decl\">Déclaré</span></li>\n   <li>Porte d’entrée : 90 cm <span class=\"st decl\">Déclaré</span></li>\n   <li>Trajet jusqu’à l’accueil <span class=\"st unk\">Inconnu</span></li>\n   <li>Équipement auditif <span class=\"st unk\">Inconnu</span></li>\n   <li>Rampe et marche signalées <span class=\"st bad\">Contradictoire</span></li>\n  </ul>\n  <p class=\"ask\"><b>À demander au cabinet :</b> le trajet jusqu’à la salle est-il de plain-pied ? Une boucle magnétique est-elle disponible ?</p>\n </figure>\n</div></div>\n\n<section aria-labelledby=\"stat-h\"><div class=\"wrap stat\">\n <div>\n  <p class=\"kicker\">France · 2022</p>\n  <p class=\"big\" aria-hidden=\"true\">15 %</p>\n  <h2 id=\"stat-h\" class=\"stat-text\"><span class=\"sr\">15 % </span>des personnes handicapées de 16 à 64 ans ont renoncé à des soins.</h2>\n  <p class=\"why\">On réserve sans savoir si l’entrée, la porte ou la salle conviendront. Sur place, une consigne dite une seule fois peut se perdre.</p>\n </div>\n <div>\n  <div class=\"bars\" role=\"img\" aria-label=\"Renoncement aux soins en 2022 : 15 % des personnes handicapées, 7 % de l’ensemble de la population.\">\n   <div><div class=\"bar-label\"><span>Personnes handicapées</span><b>15 %</b></div><div class=\"track\"><div class=\"fill\" style=\"width:100%;background:var(--green)\"></div></div></div>\n   <div><div class=\"bar-label\"><span>Ensemble de la population</span><b>7 %</b></div><div class=\"track\"><div class=\"fill\" style=\"width:46.7%;background:#a9bfae\"></div></div></div>\n  </div>\n  <p class=\"source\">Source : DREES, 2022. Personnes de 16 à 64 ans.</p>\n </div>\n</div></section>\n\n<section aria-labelledby=\"how-h\"><div class=\"wrap\">\n <p class=\"kicker\">Comment ça marche</p>\n <h2 id=\"how-h\">Du choix du cabinet jusqu’à la consultation.</h2>\n <ol class=\"steps\">\n  <li><h3>Décrire et comparer</h3><p>« Fauteuil électrique, malentendant. » Vos mots deviennent des critères que vous pouvez relire. Les cabinets sont classés sur ce qui est documenté, les obstacles connus en dernier.</p><a href=\"/cabinets\">Chercher un cabinet</a></li>\n  <li><h3>Préparer et réserver</h3><p>Une fiche de préparation liste les questions à poser au cabinet. Quand la source donne un lien Doctolib, vous réservez directement.</p><a href=\"/cabinets\">Voir les cabinets</a></li>\n  <li><h3>Suivre l’échange</h3><p>Pendant la visite ou l’appel vidéo, les paroles s’affichent à l’écran et vous pouvez répondre par écrit ou à voix haute.</p><a href=\"/consultation\">Ouvrir l’échange</a></li>\n </ol>\n</div></section>\n\n<section aria-labelledby=\"trust-h\"><div class=\"wrap\">\n <p class=\"kicker\">Confiance</p>\n <h2 id=\"trust-h\">Jamais « accessible » sans preuve.</h2>\n <p class=\"section-lede\">Chaque critère porte son origine et son ancienneté. Vous voyez jusqu’où vous fier à chaque réponse, au lieu d’un simple oui ou non.</p>\n <ul class=\"legend\">\n  <li><span class=\"st decl\">Déclaré</span><p>Renseigné dans Accès Libre, sans date de vérification.</p></li>\n  <li><span class=\"st unk\">Inconnu</span><p>Aucune donnée. Nous ne devinons pas : nous proposons la question à poser.</p></li>\n  <li><span class=\"st bad\">Contradictoire</span><p>Deux champs se contredisent. À confirmer avec le cabinet.</p></li>\n  <li class=\"later\"><span class=\"st ok\">Vérifié</span><span class=\"soon\">à venir</span><p>Confirmé par photos du cabinet ou par des patients après leur visite.</p></li>\n </ul>\n <p class=\"note\">Aujourd’hui, toutes les informations renseignées sont <b>déclaratives</b> : l’export Accès Libre ne donne pas de date de confirmation par fiche. Nous l’affichons tel quel.</p>\n</div></section>\n\n<section aria-labelledby=\"limits-h\"><div class=\"wrap\">\n <p class=\"kicker\">Ce que nous ne faisons pas</p>\n <h2 id=\"limits-h\">Un outil d’aide, pas une garantie.</h2>\n <ul class=\"limits\">\n  <li>Aucun profil de santé conservé : vos besoins restent dans la page.</li>\n  <li>Pas de créneaux ni de réservation : nous ouvrons le lien Doctolib de la fiche.</li>\n  <li>Pas un interprète ni un dossier médical : faites confirmer les consignes importantes.</li>\n  <li>Pas de score d’accessibilité universel : chaque besoin est différent.</li>\n </ul>\n</div></section>\n\n</main>\n<footer><div class=\"wrap\"><p>Données : Accès Libre — Ministère de la Transition écologique, Licence Ouverte / Etalab 2.0. Export du 24 octobre 2026, cabinets médicaux de Paris.</p><p>Statistique : DREES, 2022.</p></div></footer>\n</body></html>\n";
